<body><?php				require( $libdir."dhabiles.inc.php" );				switch ($action) {						case "view" :				print_from($IDPuntoVenta,$Fecha);			break;						default :				print_from("");			break;				} // End switch /*******************************************************************************************		funcion Listar*******************************************************************************************/function print_from($IDPuntoVenta="", $Fecha=""){ Global $dblink,$total_records,$row,$numtoshow,$Nivel,$IVA,$Mes_array,$FechaDesde, $FechaHasta; //require( "Reportes/Calc.php" ); //$Calendario = new Date_Calc;  $ReteICA =  get_field( "ReteICA","Valor","IDReteICA",1 )  ; $ReteIVA = get_field( "ReteIVA","Valor","IDReteIVA",1 ) / 100; $ReteFuente = get_field( "ReteFuente","Valor","IDReteFuente",1 ) / 100; ?>		<table width="100%">				<tr>		<td>			<table width='100%' align='left' border="0" cellspacing="0" cellpadding="2" class="bordertable">				<form action="./" name="frmPuntoVenta" method="post" name="Moviles">						<tr>							<td valign="middle"><img src="images/calendar_edit.png" border="0" alt=""></td>							<td  align='left' valign='middle' class="nav">															Desde	<input readonly type="text" name="FechaDesde" class="input" value="<?php echo fecha()?>" size="10">								<script language="JavaScript1.2">									<!--										if (!document.layers)											document.write("<img src=jscripts/imagescalendar/cal.gif onmouseover=this.style.cursor='hand' onclick='popUpCalendar(this, document.frmPuntoVenta.FechaDesde,\"yyyy-mm-dd\")' width=16 height=16 border=0>")																//-->								</script>							</td>							<td align="left" valign="middle" class="nav">																Hasta	<input readonly type="text" name="FechaHasta" class="input" value="<?php echo fecha()?>" size="10">								<script language="JavaScript1.2">									<!--										if (!document.layers)											document.write("<img src=jscripts/imagescalendar/cal.gif onmouseover=this.style.cursor='hand' onclick='popUpCalendar(this, document.frmPuntoVenta.FechaHasta,\"yyyy-mm-dd\")' width=16 height=16 border=0>")																//-->								</script>							</td>							<td  align='left' valign='middle' class="nav"><img src='images/house.png' border='0'  alt=''></td>							<td align="left" valign="middle" class="nav">Puntos de Venta	<select name="IDPuntoVenta" onchange="document.frmPuntoVenta.submit();" >									<option value="">Seleccione Un Punto de Venta</option><?php 																$qry_punto = db_query("SELECT * FROM PuntoVenta ");								while($punto = db_fetch_object($qry_punto)){									 echo "<option value=$punto->IDPuntoVenta ";if($IDPuntoVenta == $punto->IDPuntoVenta ) echo "selected"; echo ">&nbsp;&nbsp;$punto->Nombre</option>";								}							?>								</select> <input type="hidden" name="mod" value="ReporteMensual"><input type="hidden" name="action" value="view"></td>							<td align="left" valign="middle" class="nav">								<input type="submit" value="Ver Reporte" name="submit" class="submit">							</td>						</tr>				</form>			</table>			</td>		</tr>				<br>		<br>		<?php		if(!empty($IDPuntoVenta) && !empty( $FechaDesde ) && !empty( $FechaHasta ) ){		?>		<tr>		<td>&nbsp;&nbsp;&nbsp;&nbsp; <br>				<br>				&nbsp;				<table width="100%" border="0" align='center' cellspacing="1" cellpadding="0" bgcolor="#345487">				<form name="frm" action="<?php echo $PHP_SELF?>" method="post" onsubmit="return Evalua(document.frm)">				<tr>					<td class="maintitle" valign="middle">&nbsp; 																		</td>				</tr>				<?php										$array_fechas = dhabiles($FechaDesde, $FechaHasta);										//print_r( $array_fechas );										 $sql_facturas = " SELECT F.*, 											DATE_FORMAT( F.FechaFactura,'%Y-%m-%e' ) as FechaFacturaF,											SUM( F.ValorTotal ) as TotalFactura, SUM( FP.Valor ) as ValorFP,FP.*,											SUM( ( FP.Valor * ( 1 - $IVA ) ) * ( FP.Comision / 100 ) ) as ComisionFP											FROM Factura F, FormaPagoFactura FP											WHERE F.IDPuntoVenta = '$IDPuntoVenta' 											AND F.FechaFactura BETWEEN '$FechaDesde' AND '$FechaHasta' 											AND F.IDFactura = FP.IDFactura											AND FP.IDFormaPago > 2											GROUP BY FP.IDFormaPago, DATE_FORMAT( F.FechaFactura, '%Y-%c-%e' )											ORDER BY FechaFactura ASC";																$qry_facturas = db_query( $sql_facturas );										$i = 0;					$formapago = array();										while( $r_facturas = db_fetch_array( $qry_facturas ) )					{						$array_factura[$r_facturas['FechaFacturaF']][$i] = $r_facturas;						$i++;					}//end while( $r_facturas = db_fetch_array( $qry_facturas ) )					//print_r( $r_facturas );								?>								<tr>					<td class='mainbg'> 					<table width="100%" border="0" cellspacing="1" cellpadding="1">						<tr>							<td class="titlemedium" nowrap>Fecha</td>							<td class="titlemedium" align="center" nowrap>Venta</td>							<td class="titlemedium" align="center" nowrap>Comisi&oacute;n</td>										<td class="titlemedium" align="center" nowrap>Rete. Fuente</td>										<td class="titlemedium" align="center" nowrap>Valor Neto</td>										<td class="titlemedium" align="center" nowrap>Rte. IVA</td>										<td class="titlemedium" align="center" nowrap>Rte. ICA</td>										<td class="titlemedium" align="center" nowrap>Ingreso</td>									</tr>						<?php						foreach( $array_fechas as $Fecha => $valor )						{ 							$class = repetition()?"row2":"row1";							//print_r($valor);							foreach( $array_factura as $key => $datos )							{								foreach( $datos as $llave => $dato )								{									if( in_array( $key, $valor ) )									{										$Base = $dato['ValorFP'] * ( 1 - $IVA );										$ValorIVA = $dato['ValorFP'] *  $IVA ;							?>								<tr>									<td class="<?php echo $class?>" align="center" nowrap><?php echo $Fecha?></td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $ValorTotal = $dato['ValorFP'],2 ); $tValorTotal += $ValorTotal;?> </td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $Comision = $dato['ComisionFP'] ,2); $tComision += $Comision?></td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $ValorRetefuente = ( $Base * $ReteFuente ),2 ); $tValorRetefuente += $ValorRetefuente;?></td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $Neto = $ValorTotal - $Comision ,2 ); $tNeto += $Neto; ?></td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $ValorRIVA = $ValorIVA * $ReteIVA ,2 ); $tValorRIVA += $ValorRIVA; ?> </td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $ValorRICA = ( ($Base / 1000) * $ReteICA ),2); $tValorRICA += $ValorRICA; ?></td>									<td class="<?php echo $class?>" align="right" nowrap><?php echo number_format( $Ingreso = ( $Neto - $ValorRetefuente -  $ValorRIVA - $ValorRICA ) ,2 ); $tIngreso += $Ingreso; ?></td>								</tr>														<?php									}//end if								}//end forech							}//end foreach						}//end foreach( $r_facturas as $key => $valor )						?>													<tr>							<td class="titlemedium" align="right" nowrap>TOTALES</td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tValorTotal, 2) ?></td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tComision, 2) ?></td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tValorRetefuente, 2) ?></td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tNeto , 2) ?></td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tValorRIVA , 2)?></td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tValorRICA , 2)?></td>							<td class="titlemedium" align="right" nowrap><?php echo number_format( $tIngreso , 2)?></td>						</tr>																							</table>				</td>			</tr>		</form>			</table>			</td>	</tr>	<?php 	 } // END if(!empty($IDEmpresa))	?>	</table>	<?php						}// Enf function print()	?></body>